const crypto = require('crypto');
const installationId = Number($env.APROVA_CHAT_INSTALLATION_ID || 0);
if (!Number.isSafeInteger(installationId) || installationId <= 0) throw new Error('Instalação de consulta não configurada.');
const operacao = $json.operacao;
if (!['listar', 'detalhar'].includes(operacao)) throw new Error('Operação de leitura inválida.');
const texto = (nome, padrao = '') => {
  const v = $json[nome] ?? padrao;
  if (typeof v !== 'string') throw new Error('Filtro inválido.');
  return v.trim();
};
const repo = texto('repositorio');
if (repo.length > 200 || (repo && !/^[A-Za-z0-9_.-]+\/[A-Za-z0-9_.-]+$/.test(repo))) throw new Error('Informe proprietário/repositório.');
const estados = ['em_andamento','todos','pendente','mapeando_contexto','gerando','testando_sandbox','avaliando_risco','aguardando_aprovacao','aplicando','concluido','rejeitado','falhou'];
const inteiro = (nome, padrao, min, max) => {
  const v = texto(nome, String(padrao)) || String(padrao);
  if (!/^\d+$/.test(v) || !Number.isSafeInteger(Number(v)) || Number(v) < min || Number(v) > max) throw new Error('Filtro numérico inválido.');
  return Number(v);
};
const id = operacao === 'detalhar' ? texto('id') : '';
if (operacao === 'detalhar' && !/^[a-f\d]{8}-[a-f\d]{4}-[a-f\d]{4}-[a-f\d]{4}-[a-f\d]{12}$/i.test(id)) throw new Error('Informe o ID real da análise.');
const estado = operacao === 'listar' ? (texto('estado') || 'em_andamento') : '';
if (estado && !estados.includes(estado)) throw new Error('Estado inválido.');
const pagina = operacao === 'listar' ? inteiro('pagina',1,1,201) : 1;
const limite = operacao === 'listar' ? inteiro('limite',10,1,50) : 1;
const numeroPR = operacao === 'listar' ? inteiro('numero_pr',0,0,2147483647) : 0;
const caminho = '/api/analises' + (id ? '/' + id : '');
const partes = ['installation_id=' + installationId];
if (repo) partes.push('repositorio=' + encodeURIComponent(repo));
if (operacao === 'listar') {
  partes.push('estado=' + estado, 'pagina=' + pagina, 'limite=' + limite);
  if (numeroPR) partes.push('numero_pr=' + numeroPR);
}
const query = partes.join('&');
const segredo = $env.N8N_SEGREDO_ACOES;
if (!segredo) throw new Error('Autenticação da consulta não configurada.');
const timestamp = Math.floor(Date.now()/1000).toString();
const assinatura = 'sha256=' + crypto.createHmac('sha256',segredo).update(timestamp + '.GET\n' + caminho + '\n' + query).digest('hex');
const base = ($env.APROVA_API_URL || 'http://host.docker.internal:8080').replace(/\/+$/,'');
return {json:{
  operacao, installation_id:installationId, repositorio:repo, estado, pagina, limite, numero_pr:numeroPR, id,
  requisicao:{url:base+caminho+'?'+query, headers:{'X-Aprova-Timestamp':timestamp,'X-Aprova-Assinatura':assinatura}}
}};

const q = $('01 | Validar e Assinar Consulta').item.json;
const falha = (status = 'indisponivel') => ({json:{status,mensagem:status === 'nao_encontrada' ? 'Análise não encontrada no escopo autorizado.' : 'Não foi possível confirmar os dados das análises.',dados:null}});
if ($json.statusCode === 404 && q.operacao === 'detalhar') return falha('nao_encontrada');
const r = $json.body;
if ($json.statusCode !== 200 || !r || typeof r !== 'object' || Array.isArray(r) ||
    r.installation_id !== q.installation_id || !Number.isFinite(Date.parse(r.consultado_em))) return falha();
const estados = ['pendente','mapeando_contexto','gerando','testando_sandbox','avaliando_risco','aguardando_aprovacao','aplicando','concluido','rejeitado','falhou'];
const terminal = e => ['concluido','rejeitado','falhou'].includes(e);
const valido = a => a && typeof a === 'object' &&
  typeof a.id === 'string' && /^[a-f\d]{8}(-[a-f\d]{4}){3}-[a-f\d]{12}$/i.test(a.id) &&
  typeof a.repositorio === 'string' && a.repositorio.length <= 200 && /^[A-Za-z0-9_.-]+\/[A-Za-z0-9_.-]+$/.test(a.repositorio) &&
  a.repositorio.split('/').every(parte => parte !== '.' && parte !== '..') &&
  (!q.repositorio || a.repositorio.toLowerCase() === q.repositorio.toLowerCase()) &&
  Number.isSafeInteger(a.numero_pr) && a.numero_pr > 0 &&
  typeof a.sha_head === 'string' && /^([a-f\d]{40}|[a-f\d]{64})$/i.test(a.sha_head) &&
  estados.includes(a.estado) &&
  ['recebido_em','criado_em','atualizado_em'].every(c => typeof a[c] === 'string' && Number.isFinite(Date.parse(a[c])));
const seguro = a => {
  const urlRepositorio = 'https://github.com/' + a.repositorio.split('/').map(encodeURIComponent).join('/');
  return {
    ...Object.fromEntries(['id','repositorio','numero_pr','sha_head','estado','recebido_em','criado_em','atualizado_em'].map(c=>[c,a[c]])),
    url_repositorio: urlRepositorio,
    url_pr: urlRepositorio + '/pull/' + a.numero_pr,
  };
};
if (q.operacao === 'detalhar') {
  if (!valido(r.analise) || r.analise.id.toLowerCase() !== q.id.toLowerCase()) return falha();
  return {json:{status:'disponivel',consultado_em:r.consultado_em,installation_id:r.installation_id,atividade_worker:'nao_consultada',dados:seguro(r.analise)}};
}
if (r.estado !== q.estado || r.repositorio !== q.repositorio || r.numero_pr !== q.numero_pr ||
  r.pagina !== q.pagina || r.limite !== q.limite || typeof r.tem_mais !== 'boolean' ||
  !Array.isArray(r.itens) || r.itens.length > q.limite ||
  new Set(r.itens.map(a=>a?.id)).size !== r.itens.length ||
  (r.tem_mais && r.itens.length !== q.limite) ||
  r.itens.some(a=>!valido(a) || (q.numero_pr && a.numero_pr !== q.numero_pr) ||
    (q.estado === 'em_andamento' ? terminal(a.estado) : q.estado !== 'todos' && a.estado !== q.estado))) return falha();
return {json:{status:'disponivel',installation_id:r.installation_id,consultado_em:r.consultado_em,
  filtros:{repositorio:q.repositorio,estado:q.estado,numero_pr:q.numero_pr},
  pagina:r.pagina,limite:r.limite,tem_mais:r.tem_mais,proxima_pagina:r.tem_mais?r.pagina+1:null,
  quantidade_nesta_pagina:r.itens.length,atividade_worker:'nao_consultada',dados:r.itens.map(seguro),
  observacao:'Retrato atual, sem janela semanal. Em andamento inclui espera por aprovação; não garante worker ativo. Página não representa contagem global.'}};
